{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Vismodegib, a highly lipophilic, poorly soluble chlorinated heteroaromatic drug, has a measured absolute oral bioavailability of 31.8% in humans, exceeding the 20% threshold despite saturable absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Erlotinib, a lipophilic anilinoquinazoline kinase inhibitor, has an absolute oral bioavailability of about 59% in healthy subjects, demonstrating that this compound class can achieve F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "GSK269984A, despite poor-solubility physicochemical features, showed >94% absolute oral bioavailability in human solution/microdose studies, indicating that solubility concerns alone do not mandate F<20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Cinacalcet, a lipophilic drug with extensive hepatic first-pass metabolism, has an absolute bioavailability of approximately 25%, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Lapatinib, a close anilinoquinazoline analogue, has an estimated oral bioavailability of 30% in patients, above the threshold, even though it is often described as low and variable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "JNJ-38893777, a lipophilic heteroaromatic kinase inhibitor, was reported to have poor bioavailability from its original tablet formulation, providing a contradictory example, though the value is not quantified and the transferability is moderate.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The strongest transferable evidence, led by vismodegib (F=31.8%) and supported by erlotinib, lapatinib, and idelalisib, indicates that lipophilic heteroaromatic kinase-inhibitor-like molecules can achieve F>=20% despite poor solubility. The physicochemical prior is uncertain and is outweighed by direct human bioavailability data from close analogues.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data exist for the query molecule.",
    "The effect of the N-oxide moiety on solubility, permeability, and first-pass metabolism is not directly covered by the analogues.",
    "Several analogue records are qualitative or formulation-dependent, especially for lapatinib and JNJ-38893777.",
    "The exact structural match to the query is absent; transfer relies on shared lipophilic heteroaromatic and kinase-inhibitor-like features."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

